SourceCode.Declaration:
/// <summary>
/// SC WD adjustment transactions. Each record is posted to the expense journal and,
/// after successful posting, updates PurchLine.TICumulativeQty for the PO line.
/// </summary>
public class TISCWDAdjustmentTable extends common
{
}

Method.Source:
/// <summary>
/// Only project categories starting with this prefix are allowed.
/// </summary>
public static ProjCategoryId categoryPrefix()
{
    return 'SC_Provision';
}

/// <summary>
/// Only purchase orders in this pool are allowed.
/// </summary>
public static PurchPoolId purchPoolId()
{
    return 'P_SWO';
}

/// <summary>
/// Project statuses that accept SC WD adjustments.
/// </summary>
public static boolean isProjStatusAllowed(ProjStatus _status)
{
    return _status == ProjStatus::InProcess;
}

public static boolean isCategoryAllowed(ProjCategoryId _categoryId)
{
    ProjCategoryId prefix = TISCWDAdjustmentTable::categoryPrefix();

    return _categoryId && subStr(_categoryId, 1, strLen(prefix)) == prefix;
}

/// <summary>
/// First day of the current month; this date and later are not accepted.
/// </summary>
public static TransDate blockedFromDate()
{
    return dateStartMth(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
}

public void initValue()
{
    super();

    this.Posted = NoYes::No;
}

public void calcAmount()
{
    this.Amount = this.Qty * this.CostPrice;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(TISCWDAdjustmentTable, Qty):
        case fieldNum(TISCWDAdjustmentTable, CostPrice):
            this.calcAmount();
            break;

        case fieldNum(TISCWDAdjustmentTable, ProjId):
            this.PurchId      = '';
            this.PurchLineNum = 0;
            break;

        case fieldNum(TISCWDAdjustmentTable, PurchId):
            this.PurchLineNum = 0;
            break;
    }
}

public void insert()
{
    this.calcAmount();

    super();
}

public void update()
{
    this.calcAmount();

    super();
}

public boolean validateTransDate()
{
    TransDate blockedFrom = TISCWDAdjustmentTable::blockedFromDate();

    if (!this.TransDate)
    {
        return checkFailed("Date must be specified.");
    }

    if (this.TransDate >= blockedFrom)
    {
        return checkFailed(strFmt("Date %1 is not allowed. Current and future months are not accepted; the date must be before %2.", this.TransDate, blockedFrom));
    }

    return true;
}

public boolean validateProjId()
{
    ProjTable projTable;

    if (!this.ProjId)
    {
        return checkFailed("Project number must be specified.");
    }

    // ProjTable is company specific, so find() only returns projects of the current entity.
    projTable = ProjTable::find(this.ProjId);

    if (!projTable)
    {
        return checkFailed(strFmt("Project %1 does not exist in entity %2.", this.ProjId, curExt()));
    }

    if (!TISCWDAdjustmentTable::isProjStatusAllowed(projTable.Status))
    {
        return checkFailed(strFmt("Project %1 has status %2. Only projects with status %3 are allowed.", this.ProjId, projTable.Status, ProjStatus::InProcess));
    }

    return true;
}

public boolean validateCategoryId()
{
    if (!this.CategoryId)
    {
        return checkFailed("Category must be specified.");
    }

    if (!ProjCategory::exist(this.CategoryId))
    {
        return checkFailed(strFmt("Category %1 does not exist.", this.CategoryId));
    }

    if (!TISCWDAdjustmentTable::isCategoryAllowed(this.CategoryId))
    {
        return checkFailed(strFmt("Category %1 is not allowed. Only categories starting with %2 are accepted.", this.CategoryId, TISCWDAdjustmentTable::categoryPrefix()));
    }

    return true;
}

public boolean validateQty()
{
    if (!this.Qty)
    {
        return checkFailed("Quantity must be specified and cannot be zero.");
    }

    return true;
}

public boolean validateCostPrice()
{
    if (!this.CostPrice)
    {
        return checkFailed("Cost price must be specified and cannot be zero.");
    }

    return true;
}

public boolean validatePurchId()
{
    PurchTable purchTable;

    if (!this.PurchId)
    {
        return checkFailed("PO number must be specified.");
    }

    purchTable = PurchTable::find(this.PurchId);

    if (!purchTable)
    {
        return checkFailed(strFmt("PO %1 does not exist.", this.PurchId));
    }

    if (purchTable.ProjId != this.ProjId)
    {
        return checkFailed(strFmt("PO %1 does not belong to project %2.", this.PurchId, this.ProjId));
    }

    if (purchTable.PurchPoolId != TISCWDAdjustmentTable::purchPoolId())
    {
        return checkFailed(strFmt("PO %1 is in pool %2. Only POs in pool %3 are allowed.", this.PurchId, purchTable.PurchPoolId, TISCWDAdjustmentTable::purchPoolId()));
    }

    return true;
}

public boolean validatePurchLineNum()
{
    if (!this.PurchLineNum)
    {
        return checkFailed("PO line number must be specified.");
    }

    if (!PurchLine::find(this.PurchId, this.PurchLineNum))
    {
        return checkFailed(strFmt("Line %1 does not exist on PO %2.", this.PurchLineNum, this.PurchId));
    }

    return true;
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret = super(_fieldIdToCheck);

    if (ret)
    {
        switch (_fieldIdToCheck)
        {
            case fieldNum(TISCWDAdjustmentTable, TransDate):
                ret = this.validateTransDate();
                break;

            case fieldNum(TISCWDAdjustmentTable, ProjId):
                ret = this.validateProjId();
                break;

            case fieldNum(TISCWDAdjustmentTable, CategoryId):
                ret = this.validateCategoryId();
                break;

            case fieldNum(TISCWDAdjustmentTable, Qty):
                ret = this.validateQty();
                break;

            case fieldNum(TISCWDAdjustmentTable, CostPrice):
                ret = this.validateCostPrice();
                break;

            case fieldNum(TISCWDAdjustmentTable, PurchId):
                ret = this.validatePurchId();
                break;

            case fieldNum(TISCWDAdjustmentTable, PurchLineNum):
                ret = this.validatePurchLineNum();
                break;
        }
    }

    return ret;
}

/// <summary>
/// Re-runs every field rule so records created by import (Excel / data entity) are validated too.
/// </summary>
public boolean validateWrite()
{
    boolean ret = super();

    if (this.RecId && this.orig().Posted == NoYes::Yes)
    {
        return checkFailed(strFmt("The adjustment is already posted with voucher %1 and cannot be changed.", this.orig().Voucher));
    }

    ret = this.validateTransDate()      && ret;
    ret = this.validateProjId()         && ret;
    ret = this.validateCategoryId()     && ret;
    ret = this.validateQty()            && ret;
    ret = this.validateCostPrice()      && ret;
    ret = this.validatePurchId()        && ret;
    ret = this.validatePurchLineNum()   && ret;

    return ret;
}

public boolean validateDelete()
{
    boolean ret = super();

    if (ret && this.Posted == NoYes::Yes)
    {
        ret = checkFailed(strFmt("The adjustment is already posted with voucher %1 and cannot be deleted.", this.Voucher));
    }

    return ret;
}

/// <summary>
/// Project lookup limited to projects with an allowed status.
/// </summary>
public static void lookupProjId(FormControl _ctrl)
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(ProjTable), _ctrl);
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tableNum(ProjTable));

    qbds.addRange(fieldNum(ProjTable, Status)).value(queryValue(ProjStatus::InProcess));

    sysTableLookup.addLookupfield(fieldNum(ProjTable, ProjId), true);
    sysTableLookup.addLookupfield(fieldNum(ProjTable, Name));
    sysTableLookup.addLookupfield(fieldNum(ProjTable, Status));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Category lookup limited to SC_Provision* categories.
/// </summary>
public static void lookupCategoryId(FormControl _ctrl)
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(ProjCategory), _ctrl);
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tableNum(ProjCategory));

    qbds.addRange(fieldNum(ProjCategory, CategoryId)).value(strFmt('%1*', queryValue(TISCWDAdjustmentTable::categoryPrefix())));

    sysTableLookup.addLookupfield(fieldNum(ProjCategory, CategoryId), true);
    sysTableLookup.addLookupfield(fieldNum(ProjCategory, Name));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// PO lookup limited to the selected project and the P_SWO pool.
/// </summary>
public static void lookupPurchId(FormControl _ctrl, ProjId _projId)
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(PurchTable), _ctrl);
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tableNum(PurchTable));

    qbds.addRange(fieldNum(PurchTable, ProjId)).value(SysQuery::value(_projId));
    qbds.addRange(fieldNum(PurchTable, PurchPoolId)).value(queryValue(TISCWDAdjustmentTable::purchPoolId()));

    sysTableLookup.addLookupfield(fieldNum(PurchTable, PurchId), true);
    sysTableLookup.addLookupfield(fieldNum(PurchTable, PurchName));
    sysTableLookup.addLookupfield(fieldNum(PurchTable, OrderAccount));
    sysTableLookup.addLookupfield(fieldNum(PurchTable, PurchStatus));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// PO line lookup for the selected PO.
/// </summary>
public static void lookupPurchLineNum(FormControl _ctrl, PurchId _purchId)
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(PurchLine), _ctrl);
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tableNum(PurchLine));

    qbds.addRange(fieldNum(PurchLine, PurchId)).value(SysQuery::value(_purchId));
    qbds.addRange(fieldNum(PurchLine, IsDeleted)).value(queryValue(NoYes::No));

    sysTableLookup.addLookupfield(fieldNum(PurchLine, LineNumber), true);
    sysTableLookup.addLookupfield(fieldNum(PurchLine, ItemId));
    sysTableLookup.addLookupfield(fieldNum(PurchLine, Name));
    sysTableLookup.addLookupfield(fieldNum(PurchLine, PurchQty));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
